mapper.sql:
WHERE rsd.camp_id = #{campId}
  AND rsd.biz_date >= #{startDate}
  AND rsd.biz_date < #{endDate}

    AND rsd.room_category_id IN

        #{roomCategoryId}



    AND rsd.poi_id IN

        #{poiId}



    AND EXISTS (
        SELECT 1
        FROM room_category rc
        WHERE rc.room_category_id = rsd.room_category_id
          AND rc.camp_id = rsd.camp_id
          AND rc.name LIKE CONCAT('%', #{keyword}, '%')
    )

WHERE om.camp_id = #{campId} AND om.is_deleted = 0 AND om.start_at < #{endDate} AND om.end_at > #{startDate} AND om.status NOT IN ('cancelled', 'canceled') AND om.room_category_id IS NOT NULL AND om.room_id IS NOT NULL
AND om.room_category_id IN
#{roomCategoryId}
AND om.poi_id IN
#{poiId}
AND ( om.guest_name LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM room r WHERE r.room_id = om.room_id AND r.camp_id = om.camp_id AND r.room_name LIKE CONCAT('%', #{keyword}, '%') ) OR EXISTS ( SELECT 1 FROM room_category rc WHERE rc.room_category_id = om.room_category_id AND rc.camp_id = om.camp_id AND rc.name LIKE CONCAT('%', #{keyword}, '%') ) )

WHERE rsb.camp_id = #{campId}
  AND rsb.biz_date >= #{startDate}
  AND rsb.biz_date < #{endDate}
  AND rsb.status = 'closed'
  AND rsb.is_deleted = 0

    AND rsb.room_category_id IN

        #{roomCategoryId}



    AND rsb.poi_id IN

        #{poiId}



    AND (
        EXISTS (
            SELECT 1
            FROM room r
            WHERE r.room_id = rsb.room_id
              AND r.camp_id = rsb.camp_id
              AND r.room_name LIKE CONCAT('%', #{keyword}, '%')
        )
        OR EXISTS (
            SELECT 1
            FROM room_category rc
            WHERE rc.room_category_id = rsb.room_category_id
              AND rc.camp_id = rsb.camp_id
              AND rc.name LIKE CONCAT('%', #{keyword}, '%')
        )
    )

mapper.select:
SELECT COUNT(1)
FROM room_status_block rsb
WHERE rsb.camp_id = #{campId}
  AND rsb.room_id = #{roomId}
  AND rsb.biz_date = #{bizDate}
  AND rsb.status = 'closed'
  AND rsb.is_deleted = 0

SELECT COUNT(1)
FROM order_main om
WHERE om.camp_id = #{campId}
  AND om.room_id = #{roomId}
  AND om.status IN ('booked', 'checked_in')
  AND om.is_deleted = 0
  AND (
    (
      om.order_type = 'hourly_room'
      AND DATE(om.start_at) <= #{bizDate}
      AND DATE(om.end_at) >= #{bizDate}
    )
    OR (
      om.order_type != 'hourly_room'
      AND DATE(om.start_at) <= #{bizDate}
      AND DATE(om.end_at) > #{bizDate}
    )
  )

SELECT
    rsb.camp_id AS campId,
    rsb.poi_id AS poiId,
    rsb.room_category_id AS roomCategoryId,
    rsb.room_id AS roomId
FROM room_status_block rsb
WHERE rsb.camp_id = #{campId}
  AND rsb.room_category_id = #{roomCategoryId}
  AND rsb.biz_date = #{bizDate}
  AND rsb.reason = #{reason}
  AND rsb.status = 'closed'
  AND rsb.is_deleted = 0
ORDER BY rsb.room_id ASC

mapper.update:
UPDATE room_status_daily
SET availability_count = CASE WHEN availability_count > 0 THEN availability_count - 1 ELSE 0 END,
    vacant_count = CASE WHEN vacant_count > 0 THEN vacant_count - 1 ELSE 0 END,
    close_room_count = close_room_count + 1,
    updated_at = NOW()
WHERE camp_id = #{campId}
  AND poi_id = #{poiId}
  AND biz_date = #{bizDate}
  AND room_category_id = #{roomCategoryId}

UPDATE room_status_block
SET status = 'open',
    is_deleted = 1,
    updated_at = NOW(),
    updated_by = #{userId}
WHERE camp_id = #{campId}
  AND room_id = #{roomId}
  AND biz_date = #{bizDate}
  AND status = 'closed'
  AND is_deleted = 0

UPDATE room_status_block
SET status = 'open',
    is_deleted = 1,
    updated_at = NOW(),
    updated_by = #{userId}
WHERE camp_id = #{campId}
  AND room_id = #{roomId}
  AND biz_date = #{bizDate}
  AND reason = #{reason}
  AND status = 'closed'
  AND is_deleted = 0

UPDATE room_status_daily
SET availability_count = availability_count + 1,
    vacant_count = vacant_count + 1,
    close_room_count = GREATEST(close_room_count - 1, 0),
    updated_at = NOW()
WHERE camp_id = #{campId}
  AND poi_id = #{poiId}
  AND biz_date = #{bizDate}
  AND room_category_id = #{roomCategoryId}
